string address = Convert.ToString(Dynamic.Address);
if (string.IsNullOrEmpty(address)) address = ThisService.IPAddress;
try
{
    var password = ThisService.Variables.ContainsKey("RconPassword") ? Convert.ToString(ThisService.Variables["RconPassword"]) : string.Empty;
    string info;
    using (var client = RconConnect(address, ThisService.RconPort, password, 2500))
    {
        info = RconCommand(client, "info", 3000);
    }
    if (info.Length == 0) throw new Exception("RCON answered no info.");
    var name = Regex.Match(info, @"^Name:\s*(.*?)\s*(\(Uptime:[^)]*\))?\s*$", RegexOptions.Multiline).Groups[1].Value;
    var players = Regex.Match(info, @"^\s*(\d+)\s+connected", RegexOptions.Multiline);
    var season = Regex.Match(info, @"^Season:\s*(.*?)\s*$", RegexOptions.Multiline).Groups[1].Value;
    var time = Regex.Match(info, @"^Time:\s*(.*?)\s*$", RegexOptions.Multiline).Groups[1].Value;
    Globals.ReturnValue = new GameQueryResponse
    {
        Success = true,
        Status = "online",
        Protocol = "custom_script",
        Address = address,
        Hostname = address + ":" + ThisService.GamePort,
        Name = name.Length > 0 ? name : ThisService.Name,
        GameType = "HumanitZ",
        Map = string.Join(" ", new[] { season, time }.Where(s => s.Length > 0)),
        NumPlayers = players.Success ? int.Parse(players.Groups[1].Value) : 0,
        MaxPlayers = ThisService.Slots,
        NumSpectators = 0,
        MaxSpectators = 0,
        Retries = 0
    };
}
catch (Exception ex)
{
    Globals.ReturnValue = GameQueryResponse.DefaultOfflineResponse(address, "custom_script", ex.Message);
}

