const int maxWaitSeconds = 90;
var binary = System.OperatingSystem.IsWindows() ? "HumanitZServer-Win64-Shipping" : "HumanitZServer-Linux-Shipping";
var root = Path.GetFullPath((string)ThisService.RootDirectory).TrimEnd('/', '\\') + Path.DirectorySeparatorChar;

List<int> ServerPids()
{
    var pids = new List<int>();
    if (System.OperatingSystem.IsWindows())
    {
        foreach (var p in Process.GetProcessesByName(binary))
        {
            try { if (p.MainModule.FileName.StartsWith(root, StringComparison.OrdinalIgnoreCase)) pids.Add(p.Id); }
            catch { } // exited meanwhile
        }
        return pids;
    }
    // Linux: the process name is cut to 15 characters, so match the executable path instead.
    var exe = root + Path.Combine("HumanitZServer", "Binaries", "Linux", binary);
    foreach (var dir in Directory.EnumerateDirectories("/proc"))
    {
        if (!int.TryParse(Path.GetFileName(dir), out var pid)) continue;
        try
        {
            var target = new FileInfo(Path.Combine(dir, "exe")).LinkTarget;
            if (target != null && target.StartsWith(exe, StringComparison.Ordinal)) pids.Add(pid);
        }
        catch { } // gone meanwhile, or not ours to read
    }
    return pids;
}

var targets = ServerPids();
if (targets.Count == 0)
{
    ScriptConsole.WriteLine((object)"The server is not running.");
    return;
}

try
{
    var password = ThisService.Variables.ContainsKey("RconPassword") ? Convert.ToString(ThisService.Variables["RconPassword"]) : string.Empty;
    using (var client = RconConnect(ThisService.IPAddress, ThisService.RconPort, password, 5000))
    {
        var saved = RconCommand(client, "save", 30000);
        ScriptConsole.WriteLine((object)("save: " + (saved.Length > 0 ? saved : "(no reply)")));
        var shutdown = RconCommand(client, "shutdown", 5000);
        ScriptConsole.WriteLine((object)("shutdown: " + (shutdown.Length > 0 ? shutdown : "(no reply)")));
    }
}
catch (Exception ex)
{
    if (System.OperatingSystem.IsWindows())
    {
        ScriptConsole.WriteLine((object)("RCON did not answer (" + ex.Message + "); the panel stops the server without saving."));
        return;
    }
    ScriptConsole.WriteLine((object)("RCON did not answer (" + ex.Message + "); sending SIGTERM."));
    foreach (var pid in targets)
        using (var kill = Process.Start(new ProcessStartInfo("kill", new[] { "-TERM", pid.ToString() }) { UseShellExecute = false }))
            kill.WaitForExit();
}

for (var second = 1; second <= maxWaitSeconds; second++)
{
    await Task.Delay(1000, ThisCancellationToken);
    if (!ServerPids().Any(targets.Contains))
    {
        ScriptConsole.WriteLine((object)("The server exited after " + second + " s."));
        return;
    }
}
ScriptConsole.WriteLine((object)("The server did not exit within " + maxWaitSeconds + " s; the panel stops it now."));
